checker_details.tests:
from solution import add_months


def test_basic():
    assert add_months('2026-01-15', 1) == '2026-02-15'


def test_end_of_month_clamp():
    assert add_months('2026-01-31', 1) == '2026-02-28'


def test_last_day_feb_to_march():
    # Feb 28 is the last day of February, so the result is the last day of March
    assert add_months('2026-02-28', 1) == '2026-03-31'


def test_last_day_30_to_31():
    assert add_months('2026-04-30', 1) == '2026-05-31'


def test_leap_last_day():
    assert add_months('2024-02-29', 12) == '2025-02-28'


def test_leap_feb_nonlast():
    assert add_months('2023-01-29', 1) == '2023-02-28'
    assert add_months('2024-01-29', 1) == '2024-02-29'


def test_negative():
    assert add_months('2026-03-31', -1) == '2026-02-28'
    assert add_months('2026-01-15', -1) == '2025-12-15'


def test_zero():
    assert add_months('2026-02-28', 0) == '2026-02-28'
    assert add_months('2026-01-10', 0) == '2026-01-10'


def test_large_n():
    assert add_months('2026-01-15', 25) == '2028-02-15'
    assert add_months('2026-01-15', -25) == '2023-12-15'


def test_december_source():
    assert add_months('2025-12-31', 2) == '2026-02-28'
    assert add_months('2025-12-15', 1) == '2026-01-15'


def test_december_target():
    assert add_months('2026-11-30', 1) == '2026-12-31'
    assert add_months('2026-10-31', 2) == '2026-12-31'


def test_to_december_negative():
    assert add_months('2026-01-31', -1) == '2025-12-31'


def test_year_boundary_multiple():
    assert add_months('2026-12-31', 12) == '2027-12-31'
    assert add_months('2026-12-31', -12) == '2025-12-31'


def test_leap_to_leap_last_day():
    assert add_months('2023-02-28', 12) == '2024-02-29'


def test_small_year_format():
    assert add_months('0999-12-15', 1) == '1000-01-15'
